const choices = msg.payload?.choices;
if (choices && choices.length > 0) {
    msg.payload = choices[0].message.content;
} else if (msg.payload?.error) {
    msg.payload = "API 错误：" + msg.payload.error.message;
} else {
    msg.payload = "响应异常：" + JSON.stringify(msg.payload);
}
return msg;

const data = msg.payload?.data;
if (data && data.length > 0) {
    msg.url = data[0].url;
    msg.payload = data[0].url;
} else if (msg.payload?.error) {
    msg.payload = "生图失败：" + msg.payload.error.message;
} else {
    msg.payload = "响应异常：" + JSON.stringify(msg.payload);
}
return msg;

// 中枢 /llm/chat 编排：集中人设 + 记忆
const body = (typeof msg.payload === "object" && msg.payload) ? msg.payload : {};
const user = body.user || msg.user || "朋友";
const scenario = body.scenario || "default";
const userMsg = body.user_msg || body.message || "（打招呼）";
const model = body.model || "doubao";
const sysOverride = body.system || null;

const PERSONAS = {
  "大佬": "40岁，喜欢用飞牛TV看电视剧和电影，偶尔玩Xbox。用轻松自然的语气，1-2句话打招呼，可顺口问要不要继续看剧。",
  "凯文": "12岁男孩，喜欢玩Xbox游戏。用热情、孩子气的口语打招呼，1-2句，可以问要不要玩会儿游戏。",
  "爱美丽": "10岁女孩，喜欢听歌。用温柔可爱的语气，1-2句，可以问想听什么歌。",
};
const persona = PERSONAS[user] || "家里的成员。用亲切自然的口语打招呼，1-2句话，像家人闲聊。";

const now = new Date(); const h = now.getHours();
const tod = h<6?"凌晨":h<11?"早上":h<14?"中午":h<18?"下午":"晚上";
const timeHint = "当前是" + tod + "，可以结合时间自然带一句。";
const system = sysOverride || ("你是家里AI助手，正在和" + user + "聊天。" + persona + "不要自我介绍，直接说话。" + timeHint);

const key = "llm_" + scenario + "_" + user;
let history = (flow.get(key) || []).slice(-6);

msg.scenario = scenario; msg.user = user; msg.user_msg = userMsg;
msg.payload = {
  model: model,
  messages: [
    {role:"system", content: system},
    ...history,
    {role:"user", content: userMsg}
  ]
};
return msg;

msg.errorReply = true;
msg.payload = "模型服务暂时不可用，请稍后再试";
return msg;

// 仅处理 HTTP 请求；手动测试(msg.res 无)直接丢弃
if (!msg.res) return null;
let reply;
if (msg.errorReply) {
  reply = (typeof msg.payload === "string") ? msg.payload : "模型服务暂时不可用";
} else {
  reply = (typeof msg.payload === "string") ? msg.payload : "响应异常";
}
if (!msg.errorReply && msg.user) {
  const key = "llm_" + (msg.scenario||"default") + "_" + msg.user;
  let hist = (flow.get(key) || []).slice();
  if (msg.user_msg) hist.push({role:"user", content: msg.user_msg});
  hist.push({role:"assistant", content: reply});
  if (hist.length > 16) hist = hist.slice(hist.length - 16);
  flow.set(key, hist);
}
msg.payload = {reply: reply};
return msg;

const body = (typeof msg.payload==="object"&&msg.payload)?msg.payload:{};
msg.payload = body.prompt || "一只可爱的猫";
return msg;

if (!msg.res) return null;
msg.payload = {image_url: (typeof msg.payload === "string") ? msg.payload : ""};
return msg;

const body = (typeof msg.payload==="object"&&msg.payload)?msg.payload:{};
const prompt = body.prompt || "描述这张图片";
const img = body.image || "";
let imgContent;
if (/^https?:\/\//.test(img)) imgContent = {type:"image_url", image_url:{url: img}};
else imgContent = {type:"image_url", image_url:{url: "data:image/jpeg;base64," + img}};
msg.payload = {
  model: body.model || "doubao",
  messages: [ {role:"user", content: [ {type:"text", text: prompt}, imgContent ]} ]
};
return msg;

const c = msg.payload && msg.payload.choices;
if (c && c[0] && c[0].message && c[0].message.content) msg.payload = c[0].message.content;
else if (msg.payload && msg.payload.error) msg.payload = "图像理解失败";
else msg.payload = "响应异常";
return msg;

if (!msg.res) return null;
msg.payload = {reply: (typeof msg.payload === "string") ? msg.payload : "图像理解失败"};
return msg;
